    "questionAr": "احسب قيمة $\\text{pH}$ و $\\text{pOH}$ لمحلول مائي من حمض الأسيتيك تركيزه $0.040\\,\\text{M}$، علماً بأن ثابت تأين الحمض $K_a = 1.8e-5$ عند $25^\\circ\\text{C}$ (حيث $[\\text{H}_3\\text{O}^+] \\approx 8.49e-4$):",
